{
  "findings": [
    {
      "check_id": "CKV_GCP_121 is not applicable, but the concept applies",
      "title": "Cloud SQL instance has deletion protection disabled",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "MEDIUM",
      "explanation": "The Cloud SQL instance is not protected against accidental deletion, which could result in data loss."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Cloud SQL instance backup is disabled",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "MEDIUM",
      "explanation": "The Cloud SQL instance does not have backups enabled, which could result in data loss in case of a failure or deletion."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Cloud SQL instance does not require SSL/TLS for connections",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "MEDIUM",
      "explanation": "The Cloud SQL instance allows unencrypted connections, potentially exposing data in transit to interception or eavesdropping."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Lock wait logging is disabled for the Cloud SQL instance",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "LOW",
      "explanation": "The 'log_lock_waits' flag is set to 'off', which means that lock waits are not being logged, potentially making it harder to diagnose performance issues."
    }
  ],
  "patched_code": "resource \"google_sql_database_instance\" \"metadata_database\" {\n  name             = \"digital-library-content-management-platform-db-metadata\"\n  database_version = \"POSTGRES_14\"\n  region           = var.region\n  deletion_protection = true\n  settings {\n    tier = \"db-f1-micro\"\n    backup_configuration {\n      enabled = true\n    }\n    ip_configuration {\n      ipv4_enabled    = true\n      require_ssl     = true\n    }\n    database_flags {\n      name  = \"log_lock_waits\"\n      value = \"on\"\n    }\n  }\n}",
  "fix_summary": "Enabled deletion protection, backups, SSL/TLS requirement for connections, and lock wait logging for the Cloud SQL instance."
}
